#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker is created in BeginPlay with NewObject but stored in a raw pointer (UArenaScoreTracker* ScoreTracker) with no UPROPERTY, so the garbage collector is free to purge it (log line 8: 'Collecting garbage: 412 objects purged' at 21:05:13). When the first goal is scored at 21:05:27, OnGoalScored dereferences the dangling ScoreTracker pointer and crashes with EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints. Fix: declare it as UPROPERTY TObjectPtr<UArenaScoreTracker> so GC keeps it alive.",
  "no_colors_cause": "The packaged build does not contain the palette asset: /Game/Data/Palettes/DA_Primary is only referenced from C++ (LoadObject in ArenaGameMode::BeginPlay), and the packaging config (Config/DefaultGame.ini) only cooks /Game/Maps/Arena and /Game/Data/Effects (bCookAll=False), so /Game/Data/Palettes is never cooked into the pak. At runtime LogStreaming reports 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', LoadObject returns null and the game falls back to gray ('Palette is null, using fallback gray'). Fix: add +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to the packaging settings."
}
